/**
 * Aggregate performance metrics computed from a set of closed trades.
 *
 * Attributes:
 * total_trades: Total number of closed trades with a PnL value.
 * winning_trades: Number of trades with PnL > 0.
 * losing_trades: Number of trades with PnL < 0.
 * breakeven_trades: Number of trades with PnL == 0.
 * win_rate: Fraction of winning trades over total (0.0–1.0).
 * loss_rate: Fraction of losing trades over total (0.0–1.0).
 * avg_win: Average PnL of winning trades.
 * avg_loss: Average PnL of losing trades (negative value).
 * profit_factor: Gross profit divided by the absolute gross loss.
 * ``None`` when there are no losing trades.
 * expectancy: Expected PnL per trade:
 * ``win_rate * avg_win + loss_rate * avg_loss``.
 * total_pnl: Sum of PnL across all closed trades.
 * gross_profit: Sum of PnL for winning trades only (positive).
 * gross_loss: Sum of PnL for losing trades only (negative).
 * max_consecutive_wins: Longest winning streak.
 * max_consecutive_losses: Longest losing streak.
 * avg_trade_duration_seconds: Mean duration between ``opened_at`` and
 * ``closed_at`` in seconds. ``None`` if no trade has both timestamps.
 * sharpe_ratio: Annualised Sharpe ratio (risk-free rate = 0), using
 * daily PnL grouped by ``closed_at`` date. ``None`` if fewer than
 * 2 closed trades exist.
 */
export type TradeMetrics = {
    /**
     * Total number of closed trades included in this computation.
     */
    total_trades: number;
    /**
     * Number of trades with a positive PnL.
     */
    winning_trades: number;
    /**
     * Number of trades with a negative PnL.
     */
    losing_trades: number;
    /**
     * Number of trades with a PnL of exactly zero.
     */
    breakeven_trades: number;
    /**
     * Fraction of winning trades over the total number of trades (0.0–1.0). A value of 0.667 means 66.7 % of trades were winners.
     */
    win_rate: string;
    /**
     * Fraction of losing trades over the total number of trades (0.0–1.0). Complements win_rate.
     */
    loss_rate: string;
    /**
     * Average PnL of winning trades in account currency.
     */
    avg_win: string;
    /**
     * Average PnL of losing trades in account currency (negative value).
     */
    avg_loss: string;
    /**
     * Gross profit divided by the absolute value of gross loss. A profit factor above 1.0 means the strategy is profitable overall. Null when there are no losing trades.
     */
    profit_factor: (string | null);
    /**
     * Expected PnL per trade: win_rate × avg_win + loss_rate × avg_loss. Positive expectancy means the strategy is profitable on average.
     */
    expectancy: string;
    /**
     * Sum of PnL across all closed trades in account currency.
     */
    total_pnl: string;
    /**
     * Sum of PnL for winning trades only (always >= 0).
     */
    gross_profit: string;
    /**
     * Sum of PnL for losing trades only (always <= 0).
     */
    gross_loss: string;
    /**
     * Length of the longest consecutive winning streak.
     */
    max_consecutive_wins: number;
    /**
     * Length of the longest consecutive losing streak.
     */
    max_consecutive_losses: number;
    /**
     * Average duration of a trade from open to close in seconds. Null when no trade has both opened_at and closed_at set.
     */
    avg_trade_duration_seconds: (number | null);
    /**
     * Annualised Sharpe ratio assuming a risk-free rate of zero, computed from daily PnL grouped by closed_at date. Null when fewer than 2 closed trades are available.
     */
    sharpe_ratio: (string | null);
};

